import{_ as e,o as r,c as a,ak as o}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Recipes","description":"","frontmatter":{"title":"Recipes","lang":"en-US"},"headers":[],"relativePath":"recipes/index.md","filePath":"recipes/index.md","lastUpdated":1788509595000}'),s={name:"recipes/index.md"};function n(d,t,i,h,l,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h1><p>The rest of this site is organized by feature — what clustering is, what the flaky score means. These pages are organized the other way round: by the question you actually arrived with, on the morning it matters.</p><table tabindex="0"><thead><tr><th>You&#39;re asking</th><th>Recipe</th></tr></thead><tbody><tr><td>&quot;This test went red — did I break it, or is it just flaky?&quot;</td><td><a href="./regression-or-flaky.html">Regression or flake?</a></td></tr><tr><td>&quot;The selector worked yesterday and the UI moved.&quot;</td><td><a href="./broken-locator.html">Fix a broken locator</a></td></tr><tr><td>&quot;Forty tests are red and I don&#39;t know where to start.&quot;</td><td><a href="./mass-failure.html">Triage a run that went mostly red</a></td></tr><tr><td>&quot;Our suite is unreliable and I have one afternoon.&quot;</td><td><a href="./flaky-cleanup.html">Cut the flakiness that costs the most</a></td></tr><tr><td>&quot;CI takes forever and I don&#39;t know what&#39;s slow.&quot;</td><td><a href="./faster-suite.html">Cut the time the suite costs</a></td></tr></tbody></table><p>Every recipe assumes the <a href="./../reporter.html">reporter</a> is installed and has sent a few runs — that&#39;s the only hard requirement. Where a step needs more than that (the capture fixtures, an LLM key, a browser extension), it says so and gives you a route that doesn&#39;t.</p><h2 id="the-tools-each-recipe-draws-on" tabindex="-1">The tools each recipe draws on <a class="header-anchor" href="#the-tools-each-recipe-draws-on" aria-label="Permalink to &quot;The tools each recipe draws on&quot;">​</a></h2><p>Piwi has more surfaces than any one team will use. Nothing below is required; the table is here so you know what exists and what it costs to switch on.</p><table tabindex="0"><thead><tr><th>Surface</th><th>What it&#39;s for</th><th>What it needs</th></tr></thead><tbody><tr><td><strong>Dashboard</strong></td><td>Everything, by hand</td><td>The server. Always available.</td></tr><tr><td><strong><a href="./../capture-fixtures.html">Capture fixtures</a></strong></td><td>Locator healing, network timing, Web Vitals, console, ARIA snapshots</td><td>One file in your test setup, imported by your specs</td></tr><tr><td><strong><a href="./../mcp.html">MCP server</a></strong></td><td>Asking your coding agent instead of clicking</td><td>Nothing — it&#39;s built into the server at <code>/mcp</code></td></tr><tr><td><strong>REST API</strong></td><td>Scripts, dashboards of your own, CI steps</td><td>Nothing; see the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a></td></tr><tr><td><strong><a href="./../ai-diagnosis.html">AI diagnosis</a></strong></td><td>An explanation of a cluster read against your git diff</td><td>An LLM you configure. Off by default; a local model works</td></tr><tr><td><strong><a href="./../ide-integration.html">Open in IDE</a></strong></td><td>Jumping from a stack frame to the file</td><td>Per-browser config, no install</td></tr><tr><td><strong><a href="./../extension.html">Browser extension</a></strong></td><td>Picking a locator against the live page</td><td>A one-click install from the <a href="https://chromewebstore.google.com/detail/piwi-picker/pakhnokpjboejcghgcmkjlpnogfjihhe" target="_blank" rel="noreferrer">Chrome Web Store</a> (Edge included)</td></tr><tr><td><strong><a href="./../desktop.html">Desktop app</a></strong></td><td>Running all of this without Docker</td><td>Windows x64 or Apple-silicon macOS; installers aren&#39;t signed yet</td></tr><tr><td><strong><a href="./../notifications.html">Notifications</a></strong></td><td>Being told instead of looking</td><td>An email, Slack, or webhook target</td></tr></tbody></table><p>If you only ever add one thing beyond the reporter, add the <a href="./../capture-fixtures.html">capture fixtures</a> — two of the five recipes above get materially better with them, and they&#39;re a single file.</p>',8)])])}const u=e(s,[["render",n]]);export{p as __pageData,u as default};
